<?php if(!$articles):?><div class="empty-blog"><span aria-hidden="true"><?=public_icon('book')?></span><p><?=e(t('blog_empty',$lang))?></p></div><?php else:?><div class="blog-grid"><?php foreach(array_slice($articles,0,$page==='home'?3:100) as $index=>$post):?><article class="blog-card"><a class="blog-art art-<?=$index%3?>" href="<?=e(public_content_path($post))?>" tabindex="-1" aria-hidden="true"><?php if(!empty($post['cover_media_id'])): $alt=row('SELECT alt FROM media_translations WHERE media_id=? AND lang=?',[$post['cover_media_id'],$lang])['alt']??'';?><img src="/media/<?=e($post['cover_media_id'])?>?variant=webp" alt="<?=e($alt)?>" width="640" height="360" loading="lazy"><?php else:?><span>KAŞ / <?=sprintf('%02d',$index+1)?></span><b><?=public_icon('arrow-up')?></b><?php endif?></a><p class="eyebrow"><?=e($post['category'])?></p><h3><a href="<?=e(public_content_path($post))?>"><?=e($post['title'])?></a></h3><p><?=e($post['excerpt'])?></p><a class="text-link" href="<?=e(public_content_path($post))?>"><?=e(t('read_article',$lang))?> <?=public_icon('arrow-up')?></a></article><?php endforeach?></div><?php endif?>
